const translations: Record<LanguageCode, TranslationDict> = {
  'auto': zhCN,
  'zh-CN': zhCN,
  'en-US': enUS,
  'zh-TW': zhTW,
  'ja-JP': jaJP,
  'ko-KR': koKR,
  'de-DE': deDE,
  'fr-FR': frFR,
  'es-ES': esES,
  'ru-RU': ruRU,
  'pt-BR': ptBR,
  'it-IT': itIT,
  'tr-TR': trTR,
  'pl-PL': plPL,
  'vi-VN': viVN,
  'ar-SA': arSA,
};

export function t(key: string, params?: Record<string, string | number>): string {
  const targetDict = translations[resolvedLang.value] || translations['en-US'];
  let template = targetDict[key] || translations['en-US'][key] || translations['zh-CN'][key] || key;

  if (params) {
    Object.keys(params).forEach(pKey => {
      template = template.replace(new RegExp(`\\{${pKey}\\}`, 'g'), String(params[pKey]));
    });
  }

  return template;
}

export const isRtl = computed(() => {
  return resolvedLang.value === 'ar-SA';
});

export function updateDocumentDir() {
  if (typeof document !== 'undefined' && document.documentElement) {
    const isRightToLeft = resolvedLang.value === 'ar-SA';
    document.documentElement.setAttribute('dir', isRightToLeft ? 'rtl' : 'ltr');
    document.documentElement.setAttribute('lang', resolvedLang.value);
  }
}

export function setLanguage(lang: string) {
  if (Object.keys(translations).includes(lang) || lang === 'auto') {
    currentLang.value = lang as LanguageCode;
    updateDocumentDir();
  }
}
